/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【16d 语音：点气泡展开 + 去尾巴 + 两块间距】 ◆◆◆◆◆◆◆◆◆◆◆◆ */

:root {
  /* 🐕 */ --voice-split: 2px;        /* 语音块和转文字面板之间的距离 */
  /* 🐕 */ --voice-row-h: 38px;       /* 语音块高度（= 上下 padding 8+8 + 三角 22），点击区按这个算 */
}
div.chat-detail-screen,
div.chat-detail-screen .voice-msg {
