}

/* --- 1. 去掉双方语音的 Kakao 尾巴 --- */
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.voice-msg)::after {
  content: none !important;
