div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper .voice-msg .voice-controls-row,
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper .voice-msg *:has(> .voice-play-btn) {
  border-radius: var(--bubble-radius) !important;
}

/* --- 2. 转文字面板：和语音块拉开距离 --- */
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper .voice-msg .voice-transcription {
  margin: var(--voice-split) 0 0 !important;
}

/* --- 3. 「查看语音内容」：透明铺满语音块，点气泡就展开 / 收起 --- */
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-bubble-wrapper .voice-msg {
  position: relative !important;
}
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper .voice-msg .voice-transcription-toggle {
  display: block !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
