}
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper .voice-msg .voice-transcription-toggle * {
  opacity: 0 !important;
}

/* ▶ 浮在点击层上面，点它还是播放 */
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper .voice-msg .voice-play-btn {
  position: relative !important;
  z-index: 3 !important;
}
/* --- 16d 修正：点击层让开 ▶，点 ▶ 播放，点其余地方展开文字 --- */
:root {
  /* 🐕 */ --voice-btn-zone: 44px;   /* ▶ 占的宽度 = 左 padding 14 + 三角 22 + 留白 8 */
}
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper .voice-msg .voice-transcription-toggle {
  left: var(--voice-btn-zone) !important;
}
/* --- 16e 修正：变量直接挂在双方语音容器上 --- */
div.chat-detail-screen:not(#_k) .voice-msg.voice-msg-them,
div.chat-detail-screen:not(#_k) .voice-msg.voice-msg-them *,
div.chat-detail-screen:not(#_k) .voice-msg.voice-msg-me,
div.chat-detail-screen:not(#_k) .voice-msg.voice-msg-me * {
