  --voice-me-color: #111111 !important;
  --voice-waveform-gap: 0px !important;
  --voice-bar-min-width: 0px !important;
  --voice-bar-max-width: none !important;     /* 解除 4px 上限，条才能铺满 */
  --voice-bar-radius: 0px !important;
  --voice-download-display: none !important;
}
/* --- 16f：对方 / 我方波形条横向放大，盖满空隙 --- */
:root {
  /* 🐕 */ --voice-bar-stretch: 8;   /* 放大倍数；条之间还有缝就调大，相邻条叠出深色就调小 */
}
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper .voice-msg :is(.voice-waveform-bar) {
