  transform-origin: center !important;
  border-radius: 0 !important;
}
/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【16g 对方语音：播放中黄色滑过】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* App 不给对方波形更新进度，改为检测 ⏸ 图标：出现 = 正在播放 */

:root {
  /* 🐕 */ --voice-fake-dur: 8s;   /* 黄色滑满的时长，CSS 读不到语音秒数，只能写死 */
}
@keyframes kkt-voice-fill {
  from { width: 0; }
  to   { width: 100%; }
}

/* 播放中：黄色从左滑到右 */
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper .voice-msg.voice-msg-them .voice-controls-row:has(.voice-play-btn :is(rect, svg > :nth-child(2)))::before {
  content: "" !important;
