  background: #444444 !important;
  transform: none !important;
  font-size: 9px !important;
  font-weight: 600 !important;
  line-height: 1 !important;
  color: #FFFFFF !important;
  -webkit-text-fill-color: #FFFFFF !important;
  pointer-events: none !important;
  z-index: 6 !important;
}

/* --- 3. 卡片整体左右移动 --- */
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-bubble-wrapper.msg-them :is(.bubble-them-custom, .msg-plain-them):has(:is(.msg-transfer-card, .msg-redpacket-card)) {
  transform: translateX(var(--pay-shift-them)) !important;
}
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-bubble-wrapper.msg-me :is(.bubble-me-custom, .msg-plain-me):has(:is(.msg-transfer-card, .msg-redpacket-card)) {
  transform: translateX(var(--pay-shift-me)) !important;
}

/* --- 4. 卡片本体：黄色头部 + 小熊画在背景上 --- */
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper :is(.msg-transfer-card, .msg-redpacket-card):is(.msg-transfer-card, .msg-redpacket-card) {
  display: flex !important;
  flex-direction: column !important;
  align-items: stretch !important;
