  padding: 0 !important;
  background:
    var(--pay-bear) right var(--pay-bear-right) top calc(var(--pay-head-h) + var(--pay-bear-drop) - var(--pay-bear-h)) / auto var(--pay-bear-h) no-repeat,
    linear-gradient(var(--pay-yellow) 0, var(--pay-yellow) var(--pay-head-h), #FFFFFF var(--pay-head-h)) !important;
  border: none !important;
  border-radius: 14px !important;
  box-shadow: none !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
  overflow: hidden !important;
  color: #111111 !important;
}
div.chat-detail-screen:not(#_k) :is(.msg-transfer-card, .msg-redpacket-card) * {
  background: transparent !important;
  box-shadow: none !important;
  text-shadow: none !important;
  border: none !important;
}
/* 中间内容区左右留白 */
div.chat-detail-screen:not(#_k) :is(.msg-transfer-card, .msg-redpacket-card) > * {
  display: flex !important;
  flex-direction: column !important;
