}
div.chat-detail-screen:not(#_k) :is(.msg-transfer-card, .msg-redpacket-card) > * * {
  padding-left: 0 !important;
  padding-right: 0 !important;
}
/* 原来的图标、标题、分隔线、对勾、箭头、备注、🧧 都不要 */
div.chat-detail-screen:not(#_k) :is(.msg-transfer-card, .msg-redpacket-card) :is(.msg-transfer-icon, .msg-transfer-label, .msg-transfer-divider, .msg-transfer-check, .msg-transfer-chevron, .msg-transfer-subtitle, .msg-redpacket-emoji, svg, img) {
  display: none !important;
}

/* --- 5. 头部文字：송금보내요 --- */
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper :is(.msg-transfer-card, .msg-redpacket-card)::before {
