/* --- 7. 金额 + 송금했어요 --- */
div.chat-detail-screen:not(#_k) :is(.msg-transfer-card, .msg-redpacket-card) .msg-transfer-amount {
  display: block !important;
  margin: 0 !important;
  font-size: 16px !important;
  font-weight: 500 !important;
  line-height: 1.4 !important;
  color: #111111 !important;
  -webkit-text-fill-color: #111111 !important;
  text-align: left !important;
  white-space: nowrap !important;
}
div.chat-detail-screen:not(#_k) :is(.msg-transfer-card, .msg-redpacket-card) .msg-transfer-amount * {
  display: inline !important;
  margin: 0 !important;
  font-size: 16px !important;
  font-weight: 500 !important;
  line-height: 1.4 !important;
  color: #111111 !important;
  -webkit-text-fill-color: #111111 !important;
}
div.chat-detail-screen:not(#_k) :is(.msg-transfer-card, .msg-redpacket-card) .msg-transfer-amount::after {
  content: " 송금했어요" !important;
  display: inline !important;
  position: static !important;
  font-size: 16px !important;
  font-weight: 500 !important;
}
/* 红包这一行放的是祝福语，不接「송금했어요」 */
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper .msg-redpacket-card.msg-redpacket-card .msg-transfer-amount::after {
  content: none !important;
}

/* --- 8. 状态元素：上面说明文字，下面灰色按钮 --- */
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper :is(.msg-transfer-card, .msg-redpacket-card):is(.msg-transfer-card, .msg-redpacket-card) .msg-transfer-status-text {
  display: block !important;
  width: 100% !important;
  height: auto !important;
  margin: 0 0 12px !important;
  padding: 0 !important;
  background: transparent !important;
  font-size: 0 !important;
  line-height: 0 !important;
  text-align: left !important;
}
div.chat-detail-screen:not(#_k) :is(.msg-transfer-card, .msg-redpacket-card) .msg-transfer-status-text * {
  font-size: 0 !important;
}
/* 说明文字 */
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper :is(.msg-transfer-card, .msg-redpacket-card) .msg-transfer-status-text::before {
  content: "송금 받기 전까지 보낸 분은 내역 상세화면에서 취소할 수 있어요." !important;
