  position: static !important;
  margin: 4px 0 14px !important;
  padding: 0 !important;
  background: none !important;
  border: none !important;
  font-size: 13px !important;
  font-weight: 400 !important;
  line-height: 1.45 !important;
  text-align: left !important;
  color: #8E8E8E !important;
  -webkit-text-fill-color: #8E8E8E !important;
  white-space: normal !important;
  word-break: keep-all !important;
}
/* 灰色按钮：默认 송금 받기 */
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper :is(.msg-transfer-card, .msg-redpacket-card) .msg-transfer-status-text::after {
  content: "송금 받기" !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  position: static !important;
  box-sizing: border-box !important;
  width: 100% !important;
  height: 42px !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  border-radius: 8px !important;
  background: #F0F0F0 !important;
  font-size: 14px !important;
  font-weight: 500 !important;
  line-height: 1 !important;
  color: #111111 !important;
  -webkit-text-fill-color: #111111 !important;
  transform: none !important;
}

/* --- 9. 收款 / 退回：按钮换字 + 动画 --- */
@keyframes kkt-pay-done {
  0%   { transform: scale(0.94); background-color: var(--pay-yellow); color: transparent; -webkit-text-fill-color: transparent; }
  45%  { transform: scale(1.03); background-color: var(--pay-yellow); }
  100% { transform: scale(1);    background-color: #F0F0F0; }
}
/* 已收款（转账 .msg-transfer-success / 红包已拆 .is-opened） */
