  position: relative !important;
  width: 270px !important;
  min-width: 270px !important;
  max-width: 270px !important;
  height: 463px !important;
  min-height: 463px !important;
  padding: 0 !important;
  margin: 0 !important;
  border: none !important;
  border-radius: 14px !important;
  box-shadow: none !important;
  overflow: hidden !important;
  animation: none !important;
  transform: none !important;
  cursor: pointer !important;
  background-color: #FFFFFF !important;
  background-image:
    /* ⓪a 上方浅灰遮条：插画伸出绿卡顶边的部分 */
    linear-gradient(#F2F2F2, #F2F2F2),
    /* ⓪b 右侧浅灰遮条：插画伸出绿卡右边的部分（含原图白边） */
    linear-gradient(#F2F2F2, #F2F2F2),
    /* ① 四角补片：改斜切大小就改 path 里的 10 */
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='246' height='218' viewBox='0 0 246 218'><path fill='%23F2F2F2' d='M0 0H10L0 10Z M246 208V218H236Z M238 0H246V8A8 8 0 0 0 238 0Z M0 210A8 8 0 0 0 8 218H0Z'/></svg>"),
    /* ② 商品条文字：CU + 礼物名 */
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='246' height='53' viewBox='0 0 246 53'><g font-family='-apple-system,BlinkMacSystemFont,sans-serif'><text x='62' y='22' font-size='12' fill='%23999999'>Lover</text><text x='62' y='41' font-size='12.5' font-weight='600' fill='%23222222'>오늘도 너무 보고 싶어</text></g></svg>"),
    /* ③ 商品图 */
    url("https://i.postimg.cc/FsF6cHpk/IMG-6315.jpg"),
    /* ④ 横幅文字：两行 y 差 28，一起加减就能整体上下挪 */
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='246' height='165' viewBox='0 0 246 165'><g font-family='-apple-system,BlinkMacSystemFont,sans-serif' font-size='18' font-weight='700' fill='%23FFFFFF'><text x='22' y='34'>오다 주웠다</text><text x='22' y='62'>너 가져</text></g></svg>"),
    /* ⑤ 插画：礼物盒 + 手 */
    url("https://i.postimg.cc/LXXSN3BW/IMG-6313.png"),
    /* ⑥ 横幅绿底 */
    linear-gradient(#02B999, #02B999),
    /* ⑦ 商品条白底 */
    linear-gradient(#FFFFFF, #FFFFFF),
    /* ⑧ 左下角图标 */
    url("https://i.postimg.cc/jjkqV1jp/IMG-6314.png"),
    /* ⑨ 下半部分（跟着收下状态切换） */
    var(--gift-bottom),
    /* ⑩ 上半浅灰底 */
    linear-gradient(#F2F2F2, #F2F2F2) !important;
  background-repeat: no-repeat !important;
  background-position:
    0 0,                               /* ⓪a */
    258px 0,                           /* ⓪b 从绿卡右边缘开始 */
    12px 18px,                         /* ① */
    12px 183px,                        /* ② */
    21px 189px,                        /* ③ */
    12px 18px,                         /* ④ */
    68px 3px,                          /* ⑤ 插画：x 贴右边，y 比绿卡顶边高 15px */
    12px 18px,                         /* ⑥ */
    12px 183px,                        /* ⑦ */
    10px 436px,                        /* ⑧ 图标 */
    0 254px,                           /* ⑨ */
    0 0 !important;                    /* ⑩ */
  background-size:
    100% 18px,                         /* ⓪a */
    12px 183px,                        /* ⓪b */
    246px 218px,                       /* ① */
    246px 53px,                        /* ② */
    44px 42px,                         /* ③ 商品图大小 */
    246px 165px,                       /* ④ */
    204px 165px,                       /* ⑤ 插画，按原图比例 950:770 */
    246px 165px,                       /* ⑥ */
    246px 53px,                        /* ⑦ */
    22px 22px,                         /* ⑧ 图标大小 */
    270px 209px,                       /* ⑨ */
    100% 254px !important;             /* ⑩ */
}

/* 1b. 收下礼物后：第二个按钮换成「선물 받음」 */
/* 拆开后的类名指南里没写，这里先猜几个常见的；不生效就要查元素 */
div.chat-detail-screen:not(#_k) :is(
  .msg-gift-card.is-opened,
  .msg-gift-card.opened,
  .msg-gift-card.gift-opened,
  .msg-gift-card[data-opened="true"],
