  --gift-bottom: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='270' height='209' viewBox='0 0 270 209'><g font-family='-apple-system,BlinkMacSystemFont,sans-serif' font-size='14' fill='%23222222'><text x='10' y='42'>💌 함께 온 메시지</text><text x='10' y='64'>&quot;오다 주웠다.&quot;</text></g><rect x='12' y='85' width='246' height='41' rx='8' fill='%23F2F2F2'/><rect x='12' y='131' width='246' height='41' rx='8' fill='%23F2F2F2'/><g font-family='-apple-system,BlinkMacSystemFont,sans-serif' font-size='14' fill='%23222222' text-anchor='middle'><text x='135' y='110'>주문내역 보기</text><text x='135' y='156'>선물 받음</text></g><text x='38' y='197' font-family='-apple-system,BlinkMacSystemFont,sans-serif' font-size='11' fill='%23666666'>카카오톡 선물하기</text><path d='M253 188l5 5-5 5' fill='none' stroke='%23BBBBBB' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'/></svg>");
}

/* 2. 卡片自己的伪元素清掉，免得 App 原装饰压在图层上 */
div.chat-detail-screen:not(#_k) .msg-gift-card::before,
div.chat-detail-screen:not(#_k) .msg-gift-card::after {
  content: none !important;
  display: none !important;
}

/* 3. 原礼物盒：透明铺满整张卡，点击照常拆开 */
div.chat-detail-screen:not(#_k) .msg-gift-card > * {
  position: absolute !important;
  inset: 0 !important;
  width: auto !important;
  height: auto !important;
  margin: 0 !important;
  z-index: 2 !important;
  opacity: 0 !important;
  animation: none !important;
}

/* 4. 外层气泡去壳 */
div.chat-detail-screen:not(#_k):not(#_k) .msg-bubble-wrapper :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-gift-card) {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
}

